<script setup lang="ts">
import {computed,ref} from 'vue'
import {clientSurface} from '../../api'
import {onShow} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import {work,resources,requireWorkspace,canUse,goCase,navigate,selectScope,signOut,type Row} from '../../workspace'
const busy=ref(false),error=ref('')
onShow(()=>requireWorkspace())
const scopeOptions=computed<Row[]>(()=>(work.data?.scopes||[]).map(s=>({...s,label:s.role_name+' · '+(s.scope_kind==='group'?'集团范围':s.scope_kind==='self'?'本人':s.scope_kind==='authorized_patient'?'患者 '+(s.authorized_patient_name||'待核实'):resources.value.clinics?.find(c=>c.id===s.clinic_id)?.clinic_name||'门店 '+s.clinic_id)})))
async function change(e:any){busy.value=true;error.value='';try{await selectScope(Number(e.detail.value))}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><WorkspaceShell v-if="work.data" title="我的账号" active="me" back><view class="account-page"><view class="account-profile panel"><view class="account-avatar"><AppIcon name="person" :size="34"/></view><view><text class="profile-name">{{work.data.account.display_name}}</text><text class="profile-role">{{work.data.scope.role_name}}</text><text class="support">账号 {{work.data.account.login_name}} · 按实际授权办理</text></view></view><view v-if="error" class="error">{{error}}</view><view class="account-section panel"><text class="account-section-title">当前办理身份</text><picker :range="scopeOptions" range-key="label" :disabled="busy" @change="change"><view class="account-row"><view><text>{{scopeOptions.find(s=>s.id===work.data?.scope.id)?.label}}</text><text class="support">{{clientSurface==='patient'?'仅切换本人或有效授权患者事项':'仅切换已授权工作岗位与门店范围'}}</text></view><AppIcon name="down" :size="18" color="#758296"/></view></picker></view><view class="account-section panel"><text class="account-section-title">常用服务</text><button v-if="canUse('UC03')" class="account-row" @click="goCase('UC03')"><view><text>{{clientSurface==='patient'?'我的预约':'预约管理'}}</text><text class="support">{{clientSurface==='patient'?'查看安排，改期或取消':'按岗位查询、调整门店预约'}}</text></view><AppIcon name="right" :size="17"/></button><button v-if="canUse('UC14')" class="account-row" @click="goCase('UC14',{dataset:'invoices'})"><view><text>费用账单</text><text class="support">有效结算及逐项收费明细</text></view><AppIcon name="right" :size="17"/></button><button class="account-row" @click="navigate('/pages/services/index')"><view><text>服务导航</text><text class="support">按你要办的事查找全部入口</text></view><AppIcon name="right" :size="17"/></button><button v-if="canUse('UC01')" class="account-row" @click="goCase('UC01')"><view><text>患者资料与授权</text><text class="support">联系人、逐项过敏、有效代办事项</text></view><AppIcon name="right" :size="17" color="#758296"/></button><button class="account-row" @click="navigate('/pages/privacy/index')"><view><text>隐私说明</text><text class="support">信息用途与联系渠道</text></view><AppIcon name="right" :size="17" color="#758296"/></button><button v-if="clientSurface==='patient'" class="account-row" @click="navigate('/pages/access/index?mode=wechat')"><view><text>微信与账号绑定</text><text class="support">验证微信并绑定已有账号，按已授权身份办理</text></view><AppIcon name="right" :size="17" color="#758296"/></button><button v-if="clientSurface==='patient'" class="account-row" @click="navigate('/pages/access/index?mode=recover')"><view><text>找回或设置账号密码</text><text class="support">已绑定微信时可验证后重设</text></view><AppIcon name="right" :size="17" color="#758296"/></button><view class="account-row"><view><text>账号协助</text><text class="support">开通、核实或重置口令，请联系门店接待。</text></view><AppIcon name="contact" :size="20" color="#758296"/></view></view><view class="account-note"><AppIcon name="locked" :size="20"/><text>紧急联系人不自动取得代办或临床同意权限。账号按真实主体分别开通，业务保留实际操作者。</text></view><button class="logout-button" @click="signOut">退出登录</button></view></WorkspaceShell></template>
<style scoped>.account-page{max-width:760px;margin:auto;display:flex;flex-direction:column;gap:20px}.account-profile{display:flex;align-items:center;gap:19px;padding:27px}.account-avatar{width:66px;height:66px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#edf5ff}.profile-name{font-size:23px;font-weight:600;display:block}.profile-role{display:inline-flex;color:#3278cf;background:#edf5ff;border-radius:5px;padding:3px 8px;font-size:12px;margin:8px 0}.support{display:block;color:#758296;font-size:12px;line-height:1.8;margin-top:4px}.account-section{padding:21px 23px}.account-section-title{font-size:16px;font-weight:600;display:block;margin-bottom:11px}.account-row{display:flex;width:100%;align-items:center;justify-content:space-between;gap:15px;padding:17px 0;border:0;border-bottom:1px solid #e3e8ef;border-radius:0;background:transparent;text-align:left;font-size:14px}.account-row:last-child{border:0}.account-note{display:flex;gap:11px;color:#758296;font-size:12px;line-height:1.9;padding:0 4px}.logout-button{background:#fff;color:#bd4a46;margin-top:4px}@media(max-width:680px){.account-page{gap:16px}.account-profile{padding:22px 19px;gap:15px}.account-avatar{width:56px;height:56px}.profile-name{font-size:21px}.account-section{padding:18px}.account-row{font-size:13px}.account-note{font-size:11px}}</style>
